print("=== Cluster 16384 槽位与 CRC16 键槽计算 ===")
def crc16_xmodem(data):
    crc = 0
    for b in data.encode('utf-8'):
        crc ^= b << 8
        for _ in range(8):
            if crc & 0x8000:
                crc = ((crc << 1) ^ 0x1021) & 0xFFFF
            else:
                crc = (crc << 1) & 0xFFFF
    return crc
def slot_of(key):
    return crc16_xmodem(key) & 16383
keys = ["user:1000", "order:2000", "session:abc", "foo", "bar"]
print("哈希槽总数 = 16384, slot = CRC16(key) & 16383")
for k in keys:
    print("  key=%-12s -> slot=%5d" % (k, slot_of(k)))
